import sys
import json
import numpy as np
import pandas as pd


def main():
    df = pd.read_csv(sys.argv[1])
    facts = []

    def add(entity, metric, period, value, formula, money=True):
        if value is None:
            return
        try:
            v = float(value)
        except (TypeError, ValueError):
            return
        if not np.isfinite(v):
            return
        facts.append({
            "entity": str(entity),
            "metric": metric,
            "period": period,
            "value": round(v, 2) if money else round(v, 1),
            "formula": formula,
        })

    num_cols = ["Revenue_TW", "Revenue_LW", "Revenue_LY", "Units_TW", "Units_LW",
                "Orders_TW", "Orders_LW", "WoW_Pct", "YoY_Pct", "Share_Pct", "Rank"]
    for c in num_cols:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")

    # Totals
    tw_total = df["Revenue_TW"].sum(skipna=True)
    lw_total = df["Revenue_LW"].sum(skipna=True)
    ly_total = df["Revenue_LY"].sum(skipna=True)
    add("TOTAL", "revenue", "TW", tw_total, "sum(Revenue_TW)")
    add("TOTAL", "revenue", "LW", lw_total, "sum(Revenue_LW)")
    if df["Revenue_LY"].notna().any():
        add("TOTAL", "revenue", "LY", ly_total, "sum(Revenue_LY)")
    if lw_total:
        add("TOTAL", "revenue", "WoW", (tw_total - lw_total) / lw_total * 100,
            "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100", money=False)
    if df["Revenue_LY"].notna().any() and ly_total:
        add("TOTAL", "revenue", "YoY", (tw_total - ly_total) / ly_total * 100,
            "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100", money=False)
    add("TOTAL", "units", "TW", df["Units_TW"].sum(skipna=True), "sum(Units_TW)")
    add("TOTAL", "orders", "TW", df["Orders_TW"].sum(skipna=True), "sum(Orders_TW)")
    u_lw = df["Units_LW"].sum(skipna=True)
    if u_lw:
        add("TOTAL", "units", "WoW", (df["Units_TW"].sum(skipna=True) - u_lw) / u_lw * 100,
            "(sum(Units_TW) - sum(Units_LW)) / sum(Units_LW) * 100", money=False)
    o_lw = df["Orders_LW"].sum(skipna=True)
    if o_lw:
        add("TOTAL", "orders", "WoW", (df["Orders_TW"].sum(skipna=True) - o_lw) / o_lw * 100,
            "(sum(Orders_TW) - sum(Orders_LW)) / sum(Orders_LW) * 100", money=False)

    # Top entities by revenue
    top = df.dropna(subset=["Revenue_TW"]).sort_values("Revenue_TW", ascending=False)
    for _, r in top.head(5).iterrows():
        add(r["Entity"], "revenue", "TW", r["Revenue_TW"], "Revenue_TW for this entity")
    for _, r in top.head(3).iterrows():
        if pd.notna(r.get("Share_Pct")):
            add(r["Entity"], "share", "TW", r["Share_Pct"],
                "Revenue_TW / sum(Revenue_TW) * 100", money=False)
        if pd.notna(r.get("Rank")):
            add(r["Entity"], "rank", "TW", r["Rank"], "rank by Revenue_TW (1 is highest)", money=False)

    # Top 5 concentration
    if tw_total:
        add("TOTAL", "share", "TW", top.head(5)["Revenue_TW"].sum() / tw_total * 100,
            "sum(top 5 Revenue_TW) / sum(Revenue_TW) * 100", money=False)

    # Absolute WoW movers
    d = df.dropna(subset=["Revenue_TW", "Revenue_LW"]).copy()
    if not d.empty:
        d["delta"] = d["Revenue_TW"] - d["Revenue_LW"]
        up = d.sort_values("delta", ascending=False).head(3)
        for _, r in up.iterrows():
            add(r["Entity"], "revenue", "WoW", r["delta"], "Revenue_TW - Revenue_LW")
        dn = d.sort_values("delta").head(3)
        for _, r in dn.iterrows():
            add(r["Entity"], "revenue", "WoW", r["delta"], "Revenue_TW - Revenue_LW")

    # Percent WoW movers among material entities
    p = df.dropna(subset=["WoW_Pct", "Revenue_TW"]).copy()
    if not p.empty:
        thresh = p["Revenue_TW"].quantile(0.5)
        pm = p[p["Revenue_TW"] >= thresh]
        if pm.empty:
            pm = p
        for _, r in pm.sort_values("WoW_Pct", ascending=False).head(2).iterrows():
            add(r["Entity"], "revenue", "WoW", r["WoW_Pct"],
                "(Revenue_TW - Revenue_LW) / Revenue_LW * 100", money=False)
        for _, r in pm.sort_values("WoW_Pct").head(2).iterrows():
            add(r["Entity"], "revenue", "WoW", r["WoW_Pct"],
                "(Revenue_TW - Revenue_LW) / Revenue_LW * 100", money=False)

    # YoY movers
    y = df.dropna(subset=["YoY_Pct", "Revenue_TW"]).copy()
    if not y.empty:
        for _, r in y.sort_values("YoY_Pct", ascending=False).head(2).iterrows():
            add(r["Entity"], "revenue", "YoY", r["YoY_Pct"],
                "(Revenue_TW - Revenue_LY) / Revenue_LY * 100", money=False)
        for _, r in y.sort_values("YoY_Pct").head(2).iterrows():
            add(r["Entity"], "revenue", "YoY", r["YoY_Pct"],
                "(Revenue_TW - Revenue_LY) / Revenue_LY * 100", money=False)

    # Units leader
    u = df.dropna(subset=["Units_TW"]).sort_values("Units_TW", ascending=False)
    if not u.empty:
        add(u.iloc[0]["Entity"], "units", "TW", u.iloc[0]["Units_TW"], "max(Units_TW)")
    o = df.dropna(subset=["Orders_TW"]).sort_values("Orders_TW", ascending=False)
    if not o.empty:
        add(o.iloc[0]["Entity"], "orders", "TW", o.iloc[0]["Orders_TW"], "max(Orders_TW)")

    print(json.dumps(facts[:25]))


if __name__ == "__main__":
    main()
